#' FSL ApplyWarp
#'
#' FSL's applywarp wrapper to apply the results of a FNIRT registration
#'
#' @param in_file Character; file path. image to be warped **Required.**
#' @param ref_file Character; file path. reference image **Required.**
#' @param abswarp Logical. treat warp field as absolute: x' = w(x)
#' @param args Character. Additional parameters to the command
#' @param datatype Character; one of: "char", "short", "int", "float", "double". Force output data type \[char short int float double\].
#' @param field_file Character; file path. file containing warp field
#' @param interp Character; one of: "nn", "trilinear", "sinc", "spline". interpolation method
#' @param mask_file Character; file path. filename for mask image (in reference space)
#' @param out_file Character; file path. output filename
#' @param postmat Character; file path. filename for post-transform (affine matrix)
#' @param premat Character; file path. filename for pre-transform (affine matrix)
#' @param relwarp Logical. treat warp field as relative: x' = x + w(x)
#' @param superlevel Character or numeric vector. level of intermediary supersampling, a for 'automatic' or integer level. Default = 2
#' @param supersample Logical. intermediary supersampling of output, default is off
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_fsl_applywarp <- function(in_file,
                     ref_file,
                     abswarp = NULL,
                     args = NULL,
                     datatype = NULL,
                     field_file = NULL,
                     interp = NULL,
                     mask_file = NULL,
                     out_file = NULL,
                     postmat = NULL,
                     premat = NULL,
                     relwarp = NULL,
                     superlevel = NULL,
                     supersample = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("fsl.applywarp", in_file = in_file, ref_file = ref_file, abswarp = abswarp, args = args, datatype = datatype, field_file = field_file, interp = interp, mask_file = mask_file, out_file = out_file, postmat = postmat, premat = premat, relwarp = relwarp, superlevel = superlevel, supersample = supersample, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

#' FSL BET
#'
#' FSL BET wrapper for skull stripping
#'
#' @param in_file Character; file path. input file to skull strip **Required.**
#' @param args Character. Additional parameters to the command
#' @param center Character or numeric vector. center of gravity in voxels
#' @param frac Numeric. fractional intensity threshold
#' @param functional Logical. apply to 4D fMRI data
#' @param mask Logical. create binary mask image
#' @param mesh Logical. generate a vtk mesh brain surface
#' @param no_output Logical. Don't generate segmented output
#' @param out_file Character; file path. name of output skull stripped image
#' @param outline Logical. create surface outline image
#' @param padding Logical. improve BET if FOV is very small in Z (by temporarily padding end slices)
#' @param radius Integer. head radius
#' @param reduce_bias Logical. bias field and neck cleanup
#' @param remove_eyes Logical. eye & optic nerve cleanup (can be useful in SIENA)
#' @param robust Logical. robust brain centre estimation (iterates BET several times)
#' @param skull Logical. create skull image
#' @param surfaces Logical. run bet2 and then betsurf to get additional skull and scalp surfaces (includes registrations)
#' @param t2_guided Character; file path. as with creating surfaces, when also feeding in non-brain-extracted T2 (includes registrations)
#' @param threshold Logical. apply thresholding to segmented brain image and mask
#' @param vertical_gradient Numeric. vertical gradient in fractional intensity threshold (-1, 1)
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
