                     outline = NULL,
                     padding = NULL,
                     radius = NULL,
                     reduce_bias = NULL,
                     remove_eyes = NULL,
                     robust = NULL,
                     skull = NULL,
                     surfaces = NULL,
                     t2_guided = NULL,
                     threshold = NULL,
                     vertical_gradient = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("fsl.bet", in_file = in_file, args = args, center = center, frac = frac, functional = functional, mask = mask, mesh = mesh, no_output = no_output, out_file = out_file, outline = outline, padding = padding, radius = radius, reduce_bias = reduce_bias, remove_eyes = remove_eyes, robust = robust, skull = skull, surfaces = surfaces, t2_guided = t2_guided, threshold = threshold, vertical_gradient = vertical_gradient, .cwd = .cwd, .env = .env, .container = .container)
