}

#' FSL FLIRT
#'
#' FSL FLIRT wrapper for coregistration
#'
#' @param in_file Character; file path. input file **Required.**
#' @param reference Character; file path. reference file **Required.**
#' @param angle_rep Character; one of: "quaternion", "euler". representation of rotation angles
#' @param apply_isoxfm Numeric. as applyxfm but forces isotropic resampling
#' @param apply_xfm Logical. apply transformation supplied by in_matrix_file or uses_qform to use the affine matrix stored in the reference header
#' @param args Character. Additional parameters to the command
#' @param bbrslope Numeric. value of bbr slope
#' @param bbrtype Character; one of: "signed", "global_abs", "local_abs". type of bbr cost function: signed \[default\], global_abs, local_abs
#' @param bgvalue Numeric. use specified background value for points outside FOV
#' @param bins Integer. number of histogram bins
#' @param coarse_search Integer. coarse search delta angle
#' @param cost Character; one of: "mutualinfo", "corratio", "normcorr", "normmi", "leastsq", "labeldiff", "bbr". cost function
#' @param cost_func Character; one of: "mutualinfo", "corratio", "normcorr", "normmi", "leastsq", "labeldiff", "bbr". cost function
#' @param datatype Character; one of: "char", "short", "int", "float", "double". force output data type
#' @param display_init Logical. display initial matrix
#' @param dof Integer. number of transform degrees of freedom
#' @param echospacing Numeric. value of EPI echo spacing - units of seconds
#' @param fieldmap Character; file path. fieldmap image in rads/s - must be already registered to the reference image
#' @param fieldmapmask Character; file path. mask for fieldmap image
#' @param fine_search Integer. fine search delta angle
#' @param force_scaling Logical. force rescaling even for low-res images
#' @param in_matrix_file Character; file path. input 4x4 affine matrix
#' @param in_weight Character; file path. File for input weighting volume
#' @param interp Character; one of: "trilinear", "nearestneighbour", "sinc", "spline". final interpolation method used in reslicing
#' @param min_sampling Numeric. set minimum voxel dimension for sampling
#' @param no_clamp Logical. do not use intensity clamping
#' @param no_resample Logical. do not change input sampling
#' @param no_resample_blur Logical. do not use blurring on downsampling
#' @param no_search Logical. set all angular searches to ranges 0 to 0
#' @param out_file Character; file path. registered output file
#' @param out_matrix_file Character; file path. output affine matrix in 4x4 asciii format
#' @param padding_size Integer. for applyxfm: interpolates outside image by size
#' @param pedir Integer. phase encode direction of EPI - 1/2/3=x/y/z & -1/-2/-3=-x/-y/-z
#' @param ref_weight Character; file path. File for reference weighting volume
#' @param rigid2D Logical. use 2D rigid body mode - ignores dof
#' @param schedule Character; file path. replaces default schedule
#' @param searchr_x Character or numeric vector. search angles along x-axis, in degrees
#' @param searchr_y Character or numeric vector. search angles along y-axis, in degrees
#' @param searchr_z Character or numeric vector. search angles along z-axis, in degrees
#' @param sinc_width Integer. full-width in voxels
#' @param sinc_window Character; one of: "rectangular", "hanning", "blackman". sinc window
#' @param uses_qform Logical. initialize using sform or qform
#' @param verbose Integer. verbose mode, 0 is least
#' @param wm_seg Character; file path. white matter segmentation volume needed by BBR cost function
#' @param wmcoords Character; file path. white matter boundary coordinates for BBR cost function
#' @param wmnorms Character; file path. white matter boundary normals for BBR cost function
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_fsl_flirt <- function(in_file,
                     reference,
                     angle_rep = NULL,
                     apply_isoxfm = NULL,
                     apply_xfm = NULL,
                     args = NULL,
                     bbrslope = NULL,
