                     no_search = NULL,
                     out_file = NULL,
                     out_matrix_file = NULL,
                     padding_size = NULL,
                     pedir = NULL,
                     ref_weight = NULL,
                     rigid2D = NULL,
                     schedule = NULL,
                     searchr_x = NULL,
                     searchr_y = NULL,
                     searchr_z = NULL,
                     sinc_width = NULL,
