  call <- ni_call("fsl.flirt", in_file = in_file, reference = reference, angle_rep = angle_rep, apply_isoxfm = apply_isoxfm, apply_xfm = apply_xfm, args = args, bbrslope = bbrslope, bbrtype = bbrtype, bgvalue = bgvalue, bins = bins, coarse_search = coarse_search, cost = cost, cost_func = cost_func, datatype = datatype, display_init = display_init, dof = dof, echospacing = echospacing, fieldmap = fieldmap, fieldmapmask = fieldmapmask, fine_search = fine_search, force_scaling = force_scaling, in_matrix_file = in_matrix_file, in_weight = in_weight, interp = interp, min_sampling = min_sampling, no_clamp = no_clamp, no_resample = no_resample, no_resample_blur = no_resample_blur, no_search = no_search, out_file = out_file, out_matrix_file = out_matrix_file, padding_size = padding_size, pedir = pedir, ref_weight = ref_weight, rigid2D = rigid2D, schedule = schedule, searchr_x = searchr_x, searchr_y = searchr_y, searchr_z = searchr_z, sinc_width = sinc_width, sinc_window = sinc_window, uses_qform = uses_qform, verbose = verbose, wm_seg = wm_seg, wmcoords = wmcoords, wmnorms = wmnorms, .cwd = .cwd, .env = .env, .container = .container)
